import{t as e}from"./client-CKWbZYOC.js";var t={getDashboard:async t=>(await e.get(`/metrics/dashboard`,{params:{projectId:t}})).data.data,getMetrics:async(t,n,r,i)=>(await e.get(`/metrics`,{params:{projectId:t,metricName:n,startTime:r,endTime:i}})).data.data,getAlertRules:async t=>(await e.get(`/metrics/alerts`,{params:{projectId:t}})).data.data,createAlertRule:async t=>(await e.post(`/metrics/alerts`,t)).data.data,deleteAlertRule:async t=>{await e.delete(`/metrics/alerts/${t}`)},getSystemMetrics:async()=>(await e.get(`/metrics/system`)).data.data};export{t};